// Ambil pesan teks dari payload Evolution API (event messages.upsert)
const body = $input.first().json.body || {};
const data = body.data || {};
const key = data.key || {};

const event = String(body.event || '').toLowerCase().replace('_', '.');
if (event !== 'messages.upsert' || key.fromMe) return [];

let jid = String(key.remoteJid || '');
if (jid.endsWith('@g.us')) return []; // abaikan grup
if (jid.endsWith('@lid')) jid = String(key.senderPn || key.remoteJidAlt || jid);

const number = jid.split('@')[0].replace(/\D/g, '');
const msg = data.message || {};
const text = String(msg.conversation || msg.extendedTextMessage?.text || '').trim();
if (!text) return [];

// Hanya nomor Mas & Cece yang diizinkan
const normalize = (n) => String(n || '').replace(/\D/g, '');
const masNumber = normalize($env.MAS_NUMBER);
const ceceNumber = normalize($env.CECE_NUMBER);
if (!number || (number !== masNumber && number !== ceceNumber)) return [];
const defaultPenabung = number === masNumber ? 'Mas' : 'Cece';

const MONTHS = ['Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni', 'Juli', 'Agustus', 'September', 'Oktober', 'November', 'Desember'];
const now = new Date(new Date().toLocaleString('en-US', { timeZone: 'Asia/Jakarta' }));
const pad = (n) => String(n).padStart(2, '0');
const today = `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())}`;
const monthName = `${MONTHS[now.getMonth()]} ${now.getFullYear()}`;

const systemPrompt = [
  'Kamu adalah asisten pencatat tabungan pernikahan Mas & Cece.',
  'Tugasmu mengubah pesan WhatsApp berbahasa Indonesia menjadi JSON dengan skema:',
  '{"intent":"transaksi"|"rekap"|"unknown","penabung":"Mas"|"Cece"|"Bersama","tipe":"Setoran"|"Pengeluaran","kategori":string,"nominal":number,"catatan":string,"bulan":string}',
  'Aturan:',
  '- intent "rekap" jika pengirim hanya menanyakan saldo/rekap/progress tabungan.',
  '- intent "unknown" jika pesan bukan transaksi dan bukan permintaan rekap.',
  '- nominal dalam Rupiah utuh: "1.5jt"/"1,5 juta" = 1500000, "500rb"/"500k" = 500000, "2 jt" = 2000000.',
  '- penabung: "Mas" atau "Cece" jika disebut; "Bersama" jika disebut bersama/berdua; jika tidak disebut gunakan "' + defaultPenabung + '".',
  '- tipe "Pengeluaran" jika pesan berisi bayar, beli, DP, keluar, transfer ke vendor; selain itu "Setoran".',
  '- kategori contoh: "Tabungan Rutin", "Bonus & Freelance", "Venue", "Katering", "Dekorasi", "Busana", "Dokumentasi", "Lainnya". Setoran tanpa keterangan = "Tabungan Rutin".',
  '- bulan format "<NamaBulan> <Tahun>" berbahasa Indonesia; jika tidak disebut gunakan "' + monthName + '".',
  '- catatan: ringkasan singkat isi pesan.',
  'Balas HANYA dengan JSON valid tanpa teks lain.'
].join('\n');

return [{
  json: {
    number,
    text,
    defaultPenabung,
    today,
    monthName,
    geminiBody: {
      systemInstruction: { parts: [{ text: systemPrompt }] },
      contents: [{ role: 'user', parts: [{ text }] }],
      generationConfig: { responseMimeType: 'application/json', temperature: 0 }
    }
  }
}];

// Validasi hasil ekstraksi Gemini dan tentukan aksi: append | rekap | error
const src = $('Normalisasi Pesan').first().json;
const res = $input.first().json;

let parsed = {};
try {
  const raw = res.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
  parsed = JSON.parse(raw.replace(/```json|```/g, '').trim());
} catch (e) {
  parsed = { intent: 'unknown' };
}

if (parsed.intent === 'rekap') {
  return [{ json: { action: 'rekap' } }];
}

const nominal = Math.round(Number(parsed.nominal) || 0);
if (parsed.intent !== 'transaksi' || nominal <= 0) {
  return [{
    json: {
      action: 'error',
      reply: [
        'Maaf, pesannya belum bisa dipahami 🙏',
        '',
        'Contoh format:',
        '• Cece setor 1.5jt',
        '• Mas nabung 2 juta bonus freelance',
        '• Bayar DP katering 5jt',
        '• Rekap'
      ].join('\n')
    }
  }];
}

const penabung = ['Mas', 'Cece', 'Bersama'].includes(parsed.penabung) ? parsed.penabung : src.defaultPenabung;
const tipe = parsed.tipe === 'Pengeluaran' ? 'Pengeluaran' : 'Setoran';

return [{
  json: {
    action: 'append',
    row: {
      id: `TX-${Date.now()}`,
      tanggal: src.today,
      bulan: parsed.bulan || src.monthName,
      penabung,
      tipe,
      kategori: parsed.kategori || (tipe === 'Setoran' ? 'Tabungan Rutin' : 'Lainnya'),
      nominal,
      catatan: parsed.catatan || src.text,
      created_at: new Date().toISOString()
    }
  }
}];

// Hitung rekap tabungan dari seluruh baris sheet Transactions
const rows = $input.all().map((i) => i.json).filter((r) => r && (r.nominal !== undefined));
const toNumber = (v) => typeof v === 'number' ? v : Number(String(v || '').replace(/[^\d,-]/g, '').replace(',', '.')) || 0;

let mas = 0, cece = 0, expense = 0;
for (const r of rows) {
  const n = toNumber(r.nominal);
  if (/pengeluaran/i.test(String(r.tipe))) expense += n;
  else if (/cece/i.test(String(r.penabung))) cece += n;
  else if (/mas/i.test(String(r.penabung))) mas += n;
}

const target = Number($env.TARGET_AMOUNT) || 100000000;
const net = mas + cece - expense;
const remaining = Math.max(0, target - net);
const pct = Math.max(0, Math.min(100, Math.round((net / target) * 100)));
const fmt = (n) => (n < 0 ? '-Rp ' : 'Rp ') + Math.abs(Math.round(n)).toLocaleString('id-ID');
const filled = Math.round(pct / 10);
const bar = '█'.repeat(filled) + '░'.repeat(10 - filled);

const validated = $('Validasi Hasil AI').first().json;
const lines = [];
if (validated.action === 'append') {
  const r = validated.row;
  lines.push(`✅ Tercatat! ${r.penabung} ${r.tipe.toLowerCase()} ${fmt(r.nominal)}`);
  lines.push(`🏷️ ${r.kategori} · 📅 ${r.bulan}`);
  lines.push('');
}
lines.push('💍 *Rekap Tabungan Mas & Cece*');
lines.push(`Terkumpul: ${fmt(net)}`);
lines.push(`Target: ${fmt(target)}`);
lines.push(`Sisa: ${fmt(remaining)}`);
lines.push(`Progress: ${bar} ${pct}%`);
lines.push(`Mas: ${fmt(mas)} | Cece: ${fmt(cece)}`);
if (expense > 0) lines.push(`Pengeluaran: ${fmt(expense)}`);
if (remaining === 0) lines.push('', '🎉 Target tercapai! Selamat menuju hari bahagia!');

return [{ json: { reply: lines.join('\n') } }];
